@startuml

class Bookmaker {}

class Bettor {
  + bettorID : string
  + name : string
}

class Race {
  + raceID : string
  + raceName : string
}

class Runner {
  + runnerID : string
  + horseName : string
}

class Jockey {
  + jockeyID : string
  + name : string
}

class Bet {
  + betID : string
  + amount : float
  + odds : float
}

Bookmaker "1" -- "*" Bettor
Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Race "1" -- "0..1" Runner : winner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

